"use client";
import { useState } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";

export default function Projects() {
    const [currentIndex, setCurrentIndex] = useState(0);

    const nextSlide = () => {
        setCurrentIndex((prev) => (prev + 1) % projects.length);
    };

    const prevSlide = () => {
        setCurrentIndex((prev) => (prev - 1 + projects.length) % projects.length);
    };

    return (
        <section className="w-full py-16 bg-gradient-to-b from-gray-100 to-gray-300 text-center">
            <h2 className="text-4xl font-bold text-gray-900">🚀 Our Exciting Projects</h2>
            <p className="mt-3 text-lg max-w-2xl mx-auto">
                We’re constantly innovating to bring you the best study experience.
            </p>

            {/* Carousel Container */}
            <div className="relative max-w-3xl mx-auto mt-8">
                <div className="overflow-hidden relative rounded-lg shadow-lg">
                    <div
                        className="flex transition-transform duration-500 ease-out"
                        style={{ transform: `translateX(-${currentIndex * 100}%)` }}
                    >
                        {projects.map((project, index) => (
                            <div
                                key={index}
                                className="min-w-full p-6 bg-white/80 backdrop-blur-lg rounded-xl flex flex-col items-center justify-center text-center"
                            >
                                <h3 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                                    {project.icon} {project.title}
                                </h3>
                                <p className="mt-2 text-base text-gray-700">{project.description}</p>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Navigation Buttons */}
                <button
                    onClick={prevSlide}
                    className="absolute left-0 top-1/2 transform -translate-y-1/2 bg-gray-700/70 p-3 rounded-full text-white shadow-md hover:bg-gray-800 transition"
                >
                    <ChevronLeft size={24} />
                </button>
                <button
                    onClick={nextSlide}
                    className="absolute right-0 top-1/2 transform -translate-y-1/2 bg-gray-700/70 p-3 rounded-full text-white shadow-md hover:bg-gray-800 transition"
                >
                    <ChevronRight size={24} />
                </button>

                {/* Dots Indicator */}
                <div className="flex justify-center mt-4">
                    {projects.map((_, index) => (
                        <div
                            key={index}
                            className={`h-3 w-3 mx-1 rounded-full transition ${
                                currentIndex === index ? "bg-gray-900 scale-110" : "bg-gray-400"
                            }`}
                        ></div>
                    ))}
                </div>
            </div>
        </section>
    );
}

// Project Data
const projects = [
    {
        title: "Sakarya Book Space",
        icon: "📚",
        description: "Join our local walking library and read people's favorite books.",
    },
    {
        title: "Live Study Groups",
        icon: "🤝",
        description: "Connect with peers for live discussions and collaborative learning.",
    },
    {
        title: "AI Study Buddy",
        icon: "🤖",
        description: "Personalized study recommendations to help you stay on track.",
    },
    {
        title: "Virtual Lab Experience",
        icon: "🔬",
        description: "Hands-on lab simulations for a realistic learning experience.",
    },
];
